package school.magiccodex.paper;
import java.sql.*;
import java.util.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
class BagSharedSqlTest {
    Connection c;BagSharedSql sql;
    final UUID owner=UUID.randomUUID(),head=UUID.randomUUID(),snapshot=UUID.randomUUID();
    BagSnapshotBinding binding(UUID snap){return new BagSnapshotBinding(owner,snap,head,10,2,BagSnapshotBinding.hash("inv"));}
    @BeforeEach void setup()throws Exception{c=DriverManager.getConnection("jdbc:sqlite::memory:");sql=new BagSharedSql(c,false);sql.createSchemaForStaging();try(var p=c.prepareStatement("INSERT INTO codex_bag_shared_v1(uuid,head,seq,active,native_snapshot,native_hash) VALUES(?,?,10,2,?,?)")){p.setString(1,owner.toString());p.setString(2,head.toString());p.setString(3,snapshot.toString());p.setString(4,BagSnapshotBinding.hash("inv"));p.executeUpdate();}}
    @AfterEach void close()throws Exception{c.close();}
    @Test void onlyOneServerCanClaimTheExactNativeSnapshot()throws Exception{var lease=UUID.randomUUID();assertNotNull(sql.claim(owner,binding(snapshot),lease,"school"));assertNull(sql.claim(owner,binding(snapshot),UUID.randomUUID(),"wild"));assertEquals(lease,sql.load(owner).lease());}
    @Test void staleOrDifferentInventorySnapshotCannotClaim()throws Exception{assertNull(sql.claim(owner,binding(UUID.randomUUID()),UUID.randomUUID(),"wild"));var bad=new BagSnapshotBinding(owner,snapshot,head,10,2,BagSnapshotBinding.hash("other"));assertNull(sql.claim(owner,bad,UUID.randomUUID(),"wild"));assertNull(sql.load(owner).lease());}
    @Test void delayedOriginSaveCannotReleaseAnotherServersLease()throws Exception{var old=UUID.randomUUID();assertNotNull(sql.claim(owner,binding(snapshot),old,"school"));assertTrue(sql.reserveCapture(owner,old,1,binding(snapshot)));assertTrue(sql.acknowledgeNative(owner,old,binding(snapshot),snapshot,"inv",snapshot,"inv",true));var next=UUID.randomUUID();assertNotNull(sql.claim(owner,binding(snapshot),next,"wild"));assertFalse(sql.acknowledgeNative(owner,old,binding(snapshot),snapshot,"inv",snapshot,"inv",true));assertEquals(next,sql.load(owner).lease());}
    @Test void oldCaptureCannotOverwriteNewerNativeAcknowledgement()throws Exception{var lease=UUID.randomUUID();sql.claim(owner,binding(snapshot),lease,"school");var old=binding(UUID.randomUUID());var newer=binding(UUID.randomUUID());assertTrue(sql.reserveCapture(owner,lease,2,newer));assertFalse(sql.reserveCapture(owner,lease,1,old));assertFalse(sql.acknowledgeNative(owner,lease,old,old.snapshot(),"inv",old.snapshot(),"inv",true));assertTrue(sql.acknowledgeNative(owner,lease,newer,newer.snapshot(),"inv",newer.snapshot(),"inv",true));assertEquals(newer.snapshot(),sql.load(owner).nativeSnapshot());}
    @Test void nativeDbSuccessWithoutMatchingRedisDoesNotReleaseOwnership()throws Exception{var lease=UUID.randomUUID();sql.claim(owner,binding(snapshot),lease,"school");sql.reserveCapture(owner,lease,1,binding(snapshot));assertThrows(IllegalStateException.class,()->sql.acknowledgeNative(owner,lease,binding(snapshot),snapshot,"inv",UUID.randomUUID(),"inv",true));assertEquals(lease,sql.load(owner).lease());assertTrue(c.getAutoCommit());}
    @Test void pageChangeInvalidatesPreviousNativeSnapshotUntilBothStoresAcknowledge()throws Exception{var lease=UUID.randomUUID();sql.claim(owner,binding(snapshot),lease,"school");assertTrue(sql.switchPages(owner,lease,head,UUID.randomUUID(),11,1,new byte[][]{new byte[0],BagPageCodec.encodePage(Collections.nCopies(27,new byte[0])),new byte[0]}));assertNull(sql.load(owner).nativeSnapshot());assertNull(sql.claim(owner,binding(snapshot),UUID.randomUUID(),"wild"));assertFalse(sql.acknowledgeNative(owner,lease,binding(snapshot),snapshot,"inv",snapshot,"inv",true));}
    @Test void wrongLeaseAndOldHeadCannotChangePages()throws Exception{var lease=UUID.randomUUID();sql.claim(owner,binding(snapshot),lease,"school");byte[][] pages={new byte[0],new byte[0],new byte[0]};assertFalse(sql.switchPages(owner,UUID.randomUUID(),head,UUID.randomUUID(),11,1,pages));assertFalse(sql.switchPages(owner,lease,UUID.randomUUID(),UUID.randomUUID(),11,1,pages));assertFalse(sql.switchPages(owner,lease,head,UUID.randomUUID(),10,1,pages));assertEquals(10,sql.load(owner).sequence());}
    @Test void crashDoesNotExpireOrStealTheLease()throws Exception{var lease=UUID.randomUUID();sql.claim(owner,binding(snapshot),lease,"school");assertNull(sql.claim(owner,binding(snapshot),UUID.randomUUID(),"wild"));assertEquals(lease,sql.load(owner).lease());}
    @Test void cleanBootstrapCreatesOnlyANewRowAndCannotResetAnExistingPlayersPages()throws Exception{UUID fresh=UUID.randomUUID(),h=UUID.randomUUID(),lease=UUID.randomUUID();assertTrue(sql.bootstrapClean(fresh,h,lease,"school"));assertEquals(1,sql.load(fresh).active());assertEquals(0,sql.load(fresh).sequence());assertEquals(lease,sql.load(fresh).lease());assertFalse(sql.bootstrapClean(fresh,UUID.randomUUID(),UUID.randomUUID(),"wild"));assertEquals(h,sql.load(fresh).head());assertFalse(sql.bootstrapClean(owner,UUID.randomUUID(),UUID.randomUUID(),"wild"));assertEquals(head,sql.load(owner).head());}
    @Test void absentSharedRecordIsNeverImportedFromPerServerDataOrInvented()throws Exception{var id=UUID.randomUUID();var b=new BagSnapshotBinding(id,snapshot,head,10,2,BagSnapshotBinding.hash("inv"));assertNull(sql.claim(id,b,UUID.randomUUID(),"school"));assertNull(sql.load(id));}
}
